SELECT s.id, s.symbol, s.market_regime, s.market_regime_confidence, s.selected_strategy, s.atr_at_signal, s.atr_overextended, s.atr_retracement_entry_price, LEFT(s.atr_explanation,600) AS atr_expl, s.entry_authority, s.entry_authority_max_position_percent, LEFT(CAST(s.decision_path AS CHAR),5000) AS path FROM trade_signal s WHERE s.id IN (156723,159408,165412,167668,171589,176710) ORDER BY s.id